// D758 (#1864) — the Templates tab's "Generated by the platform" group:
// frontend/src/lib/generatedDocuments.js and
// frontend/src/pages/admin/contracts/GeneratedDocuments.jsx, rendered inside
// TemplateCatalog. Every title, slug and sentence in the fixtures is synthetic.
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import React from 'react';
import { contractsApi } from '../src/lib/api.js';
import { GENERATED_PILL, proseState, visibleGenerated } from '../src/lib/generatedDocuments.js';
import TemplateCatalog from '../src/pages/admin/contracts/TemplateCatalog.jsx';
import { mountContracts } from './_contracts_dom.mjs';

const REFUSAL = 'Synthetic refusal: counsel has not written this one.';
const prose = (slug, o = {}) => ({ slug, part: null, title: `Synthetic ${slug}`, has_body: false, counsel_draft: false, missing: false, ...o });
const gen = (key, title, kind, o = {}) => ({
  key, title, kind, party: 'fund', party_line: 'Axal VC GP LLC (for the Fund)', prose: [], refusal: null, thumbnail_version: `v${key.length}abcdef0123456`, ...o,
});
// The ten keys, in the Worker's order (D758 decision 1).
const TEN = [
  gen('capital_call_notice', 'Capital Call Notice', 'notice', {
    prose: [prose('capital_call_notice', { title: 'Synthetic call prose', counsel_draft: true })],
    refusal: { code: 'notice_body_missing', message: REFUSAL },
  }),
  gen('distribution_notice', 'Distribution Notice', 'notice', { prose: [prose('distribution_notice', { has_body: true })] }),
  gen('default_notice', 'Notice of Default', 'notice', { prose: [prose('default_notice')] }),
  gen('management_fee_statement', 'Management Fee Statement', 'notice', { party_line: 'Axal VC GP LLC (for the Fund), to each limited partner' }),
  gen('management_fee_invoice', 'Management Fee Invoice', 'notice', { party: 'gp', party_line: 'Axal VC GP LLC, to the Fund' }),
  gen('platform_licence_fee_invoice', 'Platform Licence Fee Invoice', 'notice', { party: 'holdings', party_line: 'Axal VC Holdings LLC, to its licensee' }),
  gen('payment_instructions_letter', 'Payment Instructions', 'notice', { party: 'per_entity', party_line: 'Issued per entity' }),
  gen('subscription_booklet', 'Subscription Booklet', 'booklet', {
    prose: [prose('securities_legend', { part: 1, title: 'Synthetic legend' }), prose('subscription', { part: 3, title: 'Synthetic subscription', has_body: true }),
      prose('syn_missing_part', { part: 4, title: null, missing: true })],
    refusal: { code: 'booklet_part_missing', message: 'Synthetic booklet refusal.', parts: [1, 4] },
  }),
  gen('structure_of_the_fund', 'Structure of the Fund', 'page', { party: 'none', party_line: 'carried by the PPM, the Subscription Booklet and the Compliance Manual' }),
  gen('certificate_of_completion', 'Certificate of completion', 'page', { party: 'none', party_line: 'appended to every signed copy' }),
];

const store = (slug, o = {}) => ({
  slug, title: `Synthetic ${slug}`, layer: 'gp', layer_label: 'Layer gp', category: 'gp', body_md: 'Body.', is_stub: 0, version: 1,
  published_version: null, has_unpublished_changes: true, usage_count: 0, kind: 'agreement', party: 'gp', format_source: 'row', updated_by: 7, ...o,
});
const ITEMS = [store('syn_store_a'), store('syn_store_b', { body_md: '', is_stub: 1 })];

const originals = { ...contractsApi };
const never = () => new Promise(() => {});
function setup(answers = {}) {
  const calls = [];
  for (const key of Object.keys(originals)) contractsApi[key] = (...args) => { calls.push([key, args]); return (answers[key] || never)(...args); };
  return calls;
}
const restore = () => Object.assign(contractsApi, originals);
const textOf = (n) => (!n ? '' : n.nodeType === 3 ? n.textContent || '' : n.childNodes?.length ? n.childNodes.map(textOf).join('') : n.textContent || '');
const testid = (view, id) => view.nodes().find((n) => view.props(n)?.['data-testid'] === id);
const cards = (view) => view.nodes().map((n) => String(view.props(n)?.['data-testid'] || '')).filter((id) => id.startsWith('generated-card-')).map((id) => id.slice('generated-card-'.length));
const within = (view, node) => [node, ...(node?.childNodes || []).flatMap((c) => within(view, c))];

async function open(answers = {}, props = {}) {
  const opened = [];
  const calls = setup({ generated: async () => ({ items: TEN }), generatedThumbnailBlob: async (key) => ({ url: `blob:syn-${key}` }), ...answers });
  const view = await mountContracts(React.createElement(TemplateCatalog, {
    items: ITEMS, authoring: true, onOpen: (slug) => opened.push(slug), onNew() {}, ...props,
  }), '/admin/contracts?tab=templates');
  await view.flush();
  return { view, calls, opened };
}

test('D758 proseState: each library row state, never "Published"', () => {
  assert.deepEqual(proseState(prose('a', { has_body: true })), { label: 'Has a body', tone: 'ok' });
  assert.deepEqual(proseState(prose('a', { counsel_draft: true })), { label: 'Stub — counsel to draft.', tone: 'warn' });
  assert.deepEqual(proseState(prose('a')), { label: 'No body in the store yet.', tone: 'neutral' });
  assert.deepEqual(proseState(prose('a', { missing: true, has_body: true })), { label: 'Not in the catalog', tone: 'info' });
  assert.equal(GENERATED_PILL, 'Generated by the platform');
});

test('D758 visibleGenerated: only under Layer · All and the state All, narrowed by title', () => {
  assert.equal(visibleGenerated(TEN).length, 10);
  assert.deepEqual(visibleGenerated(TEN, { layer: 'gp' }), []);
  assert.deepEqual(visibleGenerated(TEN, { state: 'stub' }), []);
  assert.deepEqual(visibleGenerated(TEN, { q: 'FEE' }).map((i) => i.key), ['management_fee_statement', 'management_fee_invoice', 'platform_licence_fee_invoice']);
  assert.deepEqual(visibleGenerated(null), []);
});

test('D758 the group: the header, every card, the capital call\'s copy, the booklet\'s parts, a missing row', async () => {
  const { view, opened } = await open();
  try {
    const group = textOf(testid(view, 'generated-group'));
    assert.match(group, /^Generated by the platform · 10/);
    assert.deepEqual(cards(view), TEN.map((i) => i.key), 'decision 1\'s order');
    const call = textOf(testid(view, 'generated-card-capital_call_notice'));
    for (const s of ['Capital Call Notice', 'notice · Axal VC GP LLC (for the Fund)', 'Generated by the platform', 'Text from the library:',
      'Synthetic call prose', 'Stub — counsel to draft.', REFUSAL]) assert.ok(call.includes(s), s);
    const button = within(view, testid(view, 'generated-card-capital_call_notice')).find((n) => n.tagName === 'BUTTON' && textOf(n) === 'Synthetic call prose');
    assert.ok(button, 'the row title is a button');
    view.props(button).onClick();
    assert.deepEqual(opened, ['capital_call_notice']);

    const booklet = testid(view, 'generated-card-subscription_booklet');
    const bt = textOf(booklet);
    assert.ok(bt.indexOf('Part 1 · Synthetic legend') < bt.indexOf('Part 3 · Synthetic subscription'), 'part order');
    assert.match(bt, /syn_missing_partNot in the catalog/);
    assert.ok(!within(view, booklet).some((n) => n.tagName === 'BUTTON' && textOf(n).includes('syn_missing_part')), 'a missing row has no button');
    assert.match(textOf(testid(view, 'generated-card-structure_of_the_fund')), /No library text: the platform writes every line\./);

    const inGroup = within(view, testid(view, 'generated-group'));
    const gt = textOf(testid(view, 'generated-group'));
    for (const word of ['Add body', 'Publish', 'Withdraw', 'uses', 'v1']) assert.ok(!gt.includes(word), `no ${word}`);
    assert.doesNotMatch(gt, /\d{4}|\$|••/, 'no figure, no account');
    assert.equal(inGroup.filter((n) => n.tagName === 'IMG').length, 10, 'each card draws its page 1');
    assert.ok(inGroup.filter((n) => n.tagName === 'IMG').every((n) => /^Page 1 of /.test(view.props(n).alt)));
  } finally { await view.unmount(); restore(); }
});

test('D758 the group hides under a layer or a state, and search narrows it and its count', async () => {
  const { view } = await open();
  try {
    await view.click('Stub · 1');
    assert.equal(testid(view, 'generated-group'), undefined, 'the Stub segment hides it');
    await view.click('All · 2');
    assert.ok(testid(view, 'generated-group'));
    await view.fill('Layer', 'gp');
    assert.equal(testid(view, 'generated-group'), undefined, 'one layer hides it');
    await view.fill('Layer', 'all');
    await view.fill('Search templates', 'fee');
    assert.match(textOf(testid(view, 'generated-group')), /^Generated by the platform · 3/);
    assert.equal(cards(view).length, 3);
  } finally { await view.unmount(); restore(); }
});

test('D758 thumbnails: the list\'s version in the call and the URL, the Worker\'s sentence and Retry', async () => {
  let fail = true;
  const generatedThumbnailBlob = async (key) => {
    if (fail && key === 'default_notice') { const e = new Error('Synthetic thumbnail sentence.'); e.code = 'thumbnail_unavailable'; throw e; }
    return { url: `blob:syn-${key}` };
  };
  const { view, calls } = await open({ generatedThumbnailBlob });
  try {
    await view.flush();
    const drawn = calls.filter(([k]) => k === 'generatedThumbnailBlob');
    assert.deepEqual(drawn.find(([, a]) => a[0] === 'capital_call_notice')[1], ['capital_call_notice', TEN[0].thumbnail_version]);
    const card = testid(view, 'generated-card-default_notice');
    assert.match(textOf(card), /Synthetic thumbnail sentence\.Retry/);
    fail = false;
    const retry = within(view, card).find((n) => n.tagName === 'BUTTON' && textOf(n) === 'Retry');
    const { act } = await import('react');
    await act(async () => { view.props(retry).onClick(); });
    await view.flush();
    assert.ok(within(view, testid(view, 'generated-card-default_notice')).some((n) => n.tagName === 'IMG'), 'retry draws it');
  } finally { await view.unmount(); restore(); }
  const src = readFileSync(new URL('../src/lib/api/contracts.js', import.meta.url), 'utf8');
  assert.match(src, /generated\/\$\{encodeURIComponent\(key\)\}\/thumbnail\.png\?v=\$\{encodeURIComponent\(version/, 'the URL names the version');
});

test('D758 across both groups, at most four thumbnails load at once', async () => {
  let live = 0, peak = 0;
  const release = [];
  const slow = (name) => () => new Promise((resolve) => { live += 1; peak = Math.max(peak, live); release.push(() => { live -= 1; resolve({ url: `blob:${name}` }); }); });
  const { view } = await open({ thumbnailBlob: slow('store'), generatedThumbnailBlob: slow('gen') });
  try {
    await view.flush();
    const { act } = await import('react');
    for (let i = 0; i < 30 && release.length; i += 1) await act(async () => { release.shift()(); await new Promise((r) => setTimeout(r, 0)); });
    assert.ok(peak > 0 && peak <= 4, `peak ${peak}`);
  } finally { await view.unmount(); restore(); }
});

test('D758 the list: pending draws nothing; a failure draws the header, the sentence and Retry, which reads again', async () => {
  const pending = await open({ generated: never });
  try { assert.equal(testid(pending.view, 'generated-group'), undefined); assert.doesNotMatch(pending.view.text(), /Generated by the platform/); }
  finally { await pending.view.unmount(); restore(); }
  let n = 0;
  const generated = async () => { n += 1; if (n === 1) { const e = new Error('Synthetic list sentence.'); e.code = 'generated_unreadable'; throw e; } return { items: TEN.slice(0, 2) }; };
  const { view } = await open({ generated });
  try {
    const g = textOf(testid(view, 'generated-group'));
    assert.match(g, /^Generated by the platform/);
    assert.match(g, /Synthetic list sentence\.Retry/);
    await view.click('Retry'); await view.flush();
    assert.equal(n, 2);
    assert.match(textOf(testid(view, 'generated-group')), /^Generated by the platform · 2/);
  } finally { await view.unmount(); restore(); }
});

test('D758 on a branch Worker (authoring off) the group is the same and a row still opens', async () => {
  const { view, opened } = await open({}, { authoring: false });
  try {
    assert.deepEqual(cards(view), TEN.map((i) => i.key));
    const button = within(view, testid(view, 'generated-card-default_notice')).find((n) => n.tagName === 'BUTTON' && textOf(n) === 'Synthetic default_notice');
    view.props(button).onClick();
    assert.deepEqual(opened, ['default_notice']);
  } finally { await view.unmount(); restore(); }
});

test('D758 the screen prints the Worker\'s refusal, never its own', () => {
  const src = readFileSync(new URL('../src/pages/admin/contracts/GeneratedDocuments.jsx', import.meta.url), 'utf8');
  assert.ok(!src.includes('Counsel has not written'));
  assert.ok(!src.includes('cannot be submitted yet'));
  assert.ok(!src.includes('dangerouslySetInnerHTML'));
});
